/* Risdel Books Module 16 - future relational migration reference. Google Sheets GS-014 is active. */
CREATE TABLE sales.TillMovements (Id uniqueidentifier NOT NULL PRIMARY KEY, ShiftId uniqueidentifier NOT NULL, MovementType nvarchar(30) NOT NULL, Amount decimal(18,2) NOT NULL, Reason nvarchar(500) NOT NULL, Reference nvarchar(100) NULL, CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE sales.ShiftReconciliations (Id uniqueidentifier NOT NULL PRIMARY KEY, ShiftId uniqueidentifier NOT NULL, ExpectedCash decimal(18,2) NOT NULL, CountedCash decimal(18,2) NOT NULL, Variance decimal(18,2) NOT NULL, VarianceReason nvarchar(500) NULL, Status nvarchar(30) NOT NULL, SubmittedAt datetime2 NOT NULL, ReviewedAt datetime2 NULL);
CREATE TABLE sales.CashSettlements (Id uniqueidentifier NOT NULL PRIMARY KEY, ShiftId uniqueidentifier NOT NULL, Amount decimal(18,2) NOT NULL, SettlementMethod nvarchar(30) NOT NULL, Reference nvarchar(100) NULL, SettledAt datetime2 NOT NULL);
